fn biggest<T: PartialOrd + Copy>(xs: &[T]) -> T {
    let mut m = xs[0];
    for &x in xs {
        if x > m { m = x; }
    }
    m
}
fn main() {
    println!("{} {}", biggest(&[3, 9, 2]), biggest(&[1.5, 0.5]));
}

